# Checkout Component Test Suite

The documentation includes all technical specifications. I have cataloged the behavioral requirements with precision.

```typescript
// Checkout.test.tsx
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// Test fixtures - specifications determine outcomes
const mockItems = [
  { id: '1', name: 'Widget', price: 29.99 },
  { id: '2', name: 'Gadget', price: 49.99 }
];

const validShipping = {
  street: '123 Main St',
  city: 'Springfield',
  state: 'CA',
  zip: '90210'
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'John Doe'
};

describe('Checkout Component', () => {
  const user = userEvent.setup();

  describe('Empty Cart State', () => {
    it('displays empty cart message when no items present', () => {
      render(<Checkout />, { wrapper: EmptyCartWrapper });

      expect(screen.getByRole('alert')).toHaveTextContent('Your cart is empty');
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });

  describe('Happy Path - Complete Checkout Flow', () => {
    it('completes full checkout: shipping → payment → review → confirmation', async () => {
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />, { wrapper: PopulatedCartWrapper });

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), validShipping.street);
      await user.type(screen.getByLabelText(/city/i), validShipping.city);
      await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
      await user.type(screen.getByLabelText(/zip code/i), validShipping.zip);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
      await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
      await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
      await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByRole('region', { name: /order review/i })).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByRole('status')).toHaveTextContent(/order confirmed/i);
      expect(onComplete).toHaveBeenCalled();
    });
  });

  describe('Shipping Validation', () => {
    it('displays error for empty street address', async () => {
      render(<Checkout />, { wrapper: PopulatedCartWrapper });

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      render(<Checkout />, { wrapper: PopulatedCartWrapper });

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Payment Validation', () => {
    it('rejects invalid card number', async () => {
      render(<Checkout />, { wrapper: PopulatedCartWrapper });
      await fillShippingForm(user);

      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit card number required/i)).toBeInTheDocument();
    });
  });

  describe('Loading States', () => {
    it('disables buttons during payment processing', async () => {
      render(<Checkout />, { wrapper: SlowPaymentWrapper });
      await completeToReviewStep(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    });
  });

  describe('Error Recovery', () => {
    it('displays payment error and allows retry', async () => {
      render(<Checkout />, { wrapper: FailingPaymentWrapper });
      await completeToReviewStep(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByRole('alert')).toHaveTextContent(/payment failed/i);
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  describe('Accessibility', () => {
    it('maintains focus management through steps', async () => {
      render(<Checkout />, { wrapper: PopulatedCartWrapper });

      expect(screen.getByRole('navigation', { name: /checkout progress/i })).toBeInTheDocument();
      expect(screen.getByRole('listitem', { current: 'step' })).toHaveTextContent('Shipping');
    });

    it('associates errors with inputs via aria-describedby', async () => {
      render(<Checkout />, { wrapper: PopulatedCartWrapper });
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      const streetInput = screen.getByLabelText(/street address/i);
      expect(streetInput).toHaveAttribute('aria-describedby', 'street-error');
    });
  });
});
